CREATE TABLE IF NOT EXISTS public.smarty_workouts_backup_strength_20261004 AS SELECT * FROM public.smarty_workouts WHERE category IN ('STRENGTH','MUSCLE BUILDING');
GRANT ALL ON public.smarty_workouts_backup_strength_20261004 TO service_role;
ALTER TABLE public.smarty_workouts_backup_strength_20261004 ENABLE ROW LEVEL SECURITY;
DO $do$
DECLARE w record; p record; m text; a int; c int; mid text;
BEGIN
  CREATE TEMP TABLE _sw(g int, i int, o text, n text) ON COMMIT DROP;
  CREATE TEMP TABLE _sg(id uuid, h text, g int) ON COMMIT DROP;
  FOR w IN SELECT s.id, s.main_workout, g.g FROM public.smarty_workouts s JOIN _sg g ON g.id = s.id AND md5(s.main_workout) = g.h LOOP
    m := w.main_workout; a := strpos(m, 'Main Workout'); c := a - 1 + strpos(substr(m, a), 'Cool Down');
    mid := substr(m, a, c - a);
    FOR p IN SELECT * FROM _sw WHERE g = w.g ORDER BY i LOOP mid := replace(mid, p.o, '@@' || p.i || '@@'); END LOOP;
    FOR p IN SELECT * FROM _sw WHERE g = w.g ORDER BY i LOOP mid := replace(mid, '@@' || p.i || '@@', p.n); END LOOP;
    UPDATE public.smarty_workouts SET main_workout = left(m, a - 1) || mid || substr(m, c), updated_at = now() WHERE id = w.id;
  END LOOP;
END $do$;
DO $p$ DECLARE m text; a int; c int; mid text; BEGIN
  SELECT main_workout INTO m FROM public.smarty_workouts WHERE id = 'a702bfb6-6ec0-4ea8-8eb9-bb6c7f1a4e8c' AND md5(main_workout) = '5dd19ca4a8ed993b2f6ad091804ad1fa';
  IF m IS NOT NULL THEN a := strpos(m, 'Main Workout'); c := a - 1 + strpos(substr(m, a), 'Cool Down'); mid := substr(m, a, c - a);
    UPDATE public.smarty_workouts SET main_workout = left(m, a - 1) || replace(replace(replace(replace(replace(replace(replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(mid, $q$×\ 3\ reps\ \{\{exercise:0652:Pull\-Up\}\}$q$, '@@P0@@'), $q$×\ 3\ reps\ \{\{exercise:1326:chin\-up\}\}$q$, '@@P1@@'), $q$×\ 4\ reps\ \{\{exercise:3667:side\ lying\ hip\ adduction\}\}$q$, '@@P2@@'), $q$×\ 4\ reps\ \{\{exercise:1326:chin\-up\}\}$q$, '@@P3@@'), $q$×\ 3\ reps\ \{\{exercise:0652:Pull\-Up\}\}$q$, '@@P4@@'), $q$×\ 3\ reps\ \{\{exercise:1326:chin\-up\}\}$q$, '@@P5@@'), $q$×\ 5\ reps\ \{\{exercise:3204:arms\ overhead\ full\ sit\-up\ \(male\)\}\}$q$, '@@P6@@'), '@@P0@@', $q$× 3 reps {{exercise:2330:cable lat pulldown full range of motion}}$q$), '@@P1@@', $q$× 3 reps {{exercise:0180:cable low seated row}}$q$), '@@P2@@', $q$× 4 reps {{exercise:0585:lever leg extension}}$q$), '@@P3@@', $q$× 4 reps {{exercise:0861:cable seated row}}$q$), '@@P4@@', $q$× 3 reps {{exercise:2330:cable lat pulldown full range of motion}}$q$), '@@P5@@', $q$× 3 reps {{exercise:0579:lever front pulldown}}$q$), '@@P6@@', $q$× 5 reps {{exercise:1452:lever seated crunch}}$q$) || substr(m, c), updated_at = now() WHERE id = 'a702bfb6-6ec0-4ea8-8eb9-bb6c7f1a4e8c'; END IF; END $p$;
UPDATE public.workouts w SET main_workout = s.main_workout, updated_at = now() FROM public.smarty_workouts s, public.smarty_workouts_backup_strength_20261004 b WHERE w.created_by = 'smarty:' || s.id::text AND b.id = s.id AND w.main_workout = b.main_workout AND s.main_workout <> b.main_workout AND w.status = 'created' AND w.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.set_logs l WHERE l.workout_id = w.id);